import { chromium } from '@playwright/test';const b=await chromium.launch();const p=await b.newPage();p.on('request',r=>{if(r.method()==='DELETE')console.log('DELETE request',r.url())});p.on('response',r=>{if(r.request().method()==='DELETE')console.log('DELETE response',r.status())});p.on('pageerror',e=>console.log('ERR',e.message));await p.goto('http://127.0.0.1:4000');const card=p.locator('article').first();await card.getByRole('button',{name:'Delete'}).click();const btn=p.getByRole('button',{name:'Delete bookmark'});console.log('box',await btn.boundingBox());await btn.click();await p.waitForTimeout(1500);console.log('dialog',await p.getByRole('alertdialog').count());await b.close();
JS

